example.expectedOutput:
{
"thoughtProcess": "Numbers: 1.2 lakhs, 20k. 'SIP is 1.2 lakhs per year' has an ANNUAL period. The schema expects
monthlySipCommitment (MONTHLY). Since there is a period mismatch, the SIP goes to unmappedFields with key
'annualSipCommitment'. 'rent is 20k a month' matches the MONTHLY period of monthlyRent, so it goes to
mappedFields.",
"clauseSegments": [
{"text": "My mutual fund SIP is 1.2 lakhs per year", "type": "FACT"},
{"text": "and my rent is 20k a month", "type": "FACT"}
],
"mappedFields": [
{"key": "monthlyRent", "value": "20k", "fieldType": "CURRENCY", "rawSpan": "rent is 20k a month",
"period": "MONTHLY", "relationship": "SELF", "confidenceScore": "HIGH"}
],
"unmappedFields": [
{"key": "annualSipCommitment", "value": "1.2 lakhs", "fieldType": "CURRENCY", "rawSpan": "SIP is 1.2 lakhs per
year", "period": "ANNUAL", "relationship": "SELF", "confidenceScore": "HIGH"}
],
"modifiers": [],
"intent": "DATA_INPUT"
}

